  el{ io.println(s.concat(s.concat(s.concat("FAIL ";name);" got=");got)) };
  <0
};

f=chunk(arr:@i64;k:i64):@@i64{
  let n=arr.len;
  let result=mut.@();
  lp(let i=0;i<n;i=i+k){
    let e=mut.0;
    e=i+k;
    if(e>n){e=n};
    result=result+@(arr.slice(i;e));
  };
  <result
};

